// Read B1 and a knob on A0, and print them through the ST-LINK
const int KNOB_PIN = A0;              // PA0
const int BITS = {{p:bits}};          // ADC resolution in bits
const int FULL = (1 << BITS) - 1;     // 4095 at 12 bits, 1023 at 10

void setup() {
  pinMode(USER_BTN, INPUT);           // PC13, R30 on the board pulls it up
  pinMode(LED_BUILTIN, OUTPUT);
  analogReadResolution(BITS);
  Serial.begin(115200);               // Serial goes to the ST-LINK's COM port
}

void loop() {
  bool pressed = digitalRead(USER_BTN) == LOW;  // B1 connects PC13 to GND
  digitalWrite(LED_BUILTIN, pressed ? HIGH : LOW);

  int raw = analogRead(KNOB_PIN);
  float volts = raw * 3.3 / FULL;
  Serial.print("A0=");
  Serial.print(raw);
  Serial.print(" (");
  Serial.print(volts, 2);
  Serial.print(" V) B1=");
  Serial.println(pressed ? "DOWN" : "UP");
  delay({{p:period}});
}

