// Read B1 and a knob on A0, and print them through the ST-LINK
const int KNOB_PIN = A0;              // PA0
const int BITS = 12;          // ADC resolution in bits
const int FULL = (1 << BITS) - 1;     // 4095 at 12 bits, 1023 at 10

void setup() {
  pinMode(USER_BTN, INPUT);           // PC13, R30 on the board pulls it up
  pinMode(LED_BUILTIN, OUTPUT);
  analogReadResolution(BITS);
  Serial.begin(115200);               // Serial goes to the ST-LINK's COM port
