  digitalWrite(LED_BUILTIN, pressed ? HIGH : LOW);

  int raw = analogRead(KNOB_PIN);
  float volts = raw * 3.3 / FULL;
  Serial.print("A0=");
  Serial.print(raw);
  Serial.print(" (");
  Serial.print(volts, 2);
  Serial.print(" V) B1=");
